package io.knowledgebrain.gateway;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;
class CourseProgressRouteTest {
 @Test void contextBelongsToCollaborationAndPrivateProgressBelongsToLearning(){String id="01900000-0000-7000-8000-000000000001",base="/api/groups/"+id+"/courses/"+id;assertEquals("collaboration",GatewayRoute.select("GET",base+"/learning-context").service());for(String path:List.of(base+"/my-progress",base+"/my-progress/revisions"))assertEquals("learning",GatewayRoute.select("GET",path).service());assertEquals("learning",GatewayRoute.select("PUT",base+"/my-progress/studies/"+id).service());assertNull(GatewayRoute.select("PUT",base+"/my-progress"));assertNull(GatewayRoute.select("GET",base+"/my-progress/participants/"+id));assertNull(GatewayRoute.select("POST",base+"/my-progress"));}
 @Test void privateHistoryQueryRejectsParticipantSpoofingAndOversizedPages(){var f=new GroupProxyTest();assertDoesNotThrow(f::init);String path="/api/groups/"+f.id+"/courses/"+f.id+"/my-progress/revisions";for(String query:List.of("participantId="+f.id,"limit=11","limit=1&limit=2","before=0")){var r=f.request("GET",path);r.setQueryString(query);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(r));}verifyNoInteractions(f.transport);}
}
